class Account{private final String number;private double balance;Account(String number,double balance){this.number=number;this.balance=balance;}void deposit(double amount){if(amount>0)balance+=amount;}boolean withdraw(double amount){if(amount<=0||amount>balance)return false;balance-=amount;return true;}public String toString(){return number+" "+balance;}}class Main{public static void main(String[] args){Account account=new Account("CB101",5000);account.deposit(1000);System.out.println(account.withdraw(1500));System.out.println(account);}}
